        new_l = []
        if not l or l[0].startswith("#END#"):
            continue
        c_old = l[0].split("#")[2]
        for c in l[1:]:
            if c.split("#")[2] == c_old:
                new_l.append(c_old)
            c_old = c.split("#")[2]
        filtered_list.append(new_l)

    filtered_list = [f for f in filtered_list if len(f) >= 2]
    return filtered_list

for fname in os.listdir("callgraph_seq"):
    path = os.path.join("callgraph_seq", fname)
    with open(path) as f:
        seq_calls = json.load(f)
    fs = generate_filtered_sequences(seq_calls)
    for seq in fs:
        for name in seq:
            if "isidentifier" in name:
                print("FILE:", fname)
                print("SEQ:", " · ".join(seq))
                print()
                break
